package com.homeassistant;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("homeassistant")
public interface HomeassistantConfig extends Config
{
	String CONFIG_GROUP = "homeassistant";

	@ConfigSection(
			name = "Homeassistant",
			description = "Homeassistant connection settings",
			position = 100
	)
	String homeassistantSection = "Homeassistant";

	@ConfigSection(
			name = "Entities",
			description = "Select which entites you want to update in homeassistant",
			position = 200
	)
	String entitiesSection = "Entities";

	@ConfigSection(
			name = "Events",
			description = "Select which events you want to send to homeassistant",
			position = 300
	)
	String eventsSection = "Events";

	@ConfigSection(
			name = "Miscellaneous",
			description = "Some miscellaneous settings",
			position = 400
	)
	String miscellaneousSection = "Miscellaneous";

	@ConfigSection(
			name = "Debug",
			description = "Debug settings",
			position = 500
	)
	String DebugSection = "Debug";

	/*
		Homeassistant section
	 */

	@ConfigItem(
			keyName = "homeassistant_url",
			name = "Homeassistant Base URL",
			description = "example: http://homeassistant.local:8123",
			section = homeassistantSection,
			position = 101
	)
	default String homeassistantUrl()
	{
		return "";
	}

	@ConfigItem(
			keyName = "homeassistant_token",
			name = "Homeassistant Access token",
			description = "Your home assistant access token",
			section = homeassistantSection,
			position = 102
	)
	default String homeassistantToken()
	{
		return "";
	}

	@ConfigItem(
			keyName = "validate_token",
			name = "Validate Home Assistant Token",
			description = "Turn on to validate your homeassistant setup, will provide details in game messages. ",
			section = homeassistantSection,
			position = 103
	)
	default boolean validateToken()
	{
		return false;
	}

	/*
		Entities section
	 */

	@ConfigItem(
			keyName = "farmingpatches",
			name = "Farming patches",
			description = "Update farming patches entities",
			section = entitiesSection,
			position = 201
	)
	default boolean farmingPatches() {
		return true;
	}

	@ConfigItem(
			keyName = "farmingcontract",
			name = "Farming contract",
			description = "Update farming contract entity",
			section = entitiesSection,
			position = 202
	)
	default boolean farmingContract() {
		return true;
	}

	@ConfigItem(
			keyName = "birdhouses",
			name = "Bird houses",
			description = "Update birdhouse timer entities",
			section = entitiesSection,
			position = 203
	)
	default boolean birdHouses() {
		return true;
	}

	@ConfigItem(
			keyName = "dailies",
			name = "Dailies",
			description = "Update dailies entities (Battlestaves, sand etc)",
			section = entitiesSection,
			position = 203
	)
	default boolean dailies() {
		return true;
	}

	@ConfigItem(
			keyName = "player_online_status",
			name = "Player online status",
			description = "Update player online status, updates the status and world",
			section = entitiesSection,
			position = 204
	)
	default boolean playerOnlineStatus() {
		return false;
	}

	@ConfigItem(
			keyName = "player_health",
			name = "Player health",
			description = "Update player health, this can result in a lot of calls",
			section = entitiesSection,
			position = 205
	)
	default boolean playerHealth() {
		return false;
	}

	@ConfigItem(
			keyName = "player_prayer",
			name = "Player prayer",
			description = "Update player prayer, this can result in a lot of calls",
			section = entitiesSection,
			position = 206
	)
	default boolean playerPrayer() {
		return false;
	}

	@ConfigItem(
			keyName = "player_special_attack",
			name = "Player special attack %",
			description = "Update player special attack",
			section = entitiesSection,
			position = 207
	)
	default boolean playerSpecialAttack() {
		return false;
	}

	@ConfigItem(
			keyName = "player_run_energy",
			name = "Player run energy %",
			description = "Update player run energy, this can result in a lot of calls",
			section = entitiesSection,
			position = 208
	)
	default boolean playerRunEnergy() {
		return false;
	}

	@ConfigItem(
			keyName = "player_status_effects",
			name = "Player status effects",
			description = "Will update for poison and venom (more soon)",
			section = entitiesSection,
			position = 209
	)
	default boolean playerStatusEffects() {
		return false;
	}

	@ConfigItem(
			keyName = "aggression_timer",
			name = "Aggression timer",
			description = "Updates aggression timer updates to homeassistant, this includes status, if applicable time and ticks",
			section = entitiesSection,
			position = 210
	)
	default boolean aggressionTimer() {
		return false;
	}

	@ConfigItem(
			keyName = "skill_boosts",
			name = "Skill boosts",
			description = "Updates all skill boosts, this includes potions and debuffs",
			section = entitiesSection,
			position = 210
	)
	default boolean skillBoosts() {
		return false;
	}

	@ConfigItem(
			keyName = "slayer_task",
			name = "Slayer task",
			description = "Sends the current slayer task, counts and location. Requires RuneLite's own Slayer plugin to be enabled",
			section = entitiesSection,
			position = 212
	)
	default boolean sendSlayerTask() {
		return false;
	}

	@ConfigItem(
			keyName = "quest_progress",
			name = "Quest progress",
			description = "Sends the quest being worked on as its progress steps up, with quest points and completion counts",
			section = entitiesSection,
			position = 213
	)
	default boolean sendQuestProgress() {
		return false;
	}

	@ConfigItem(
			keyName = "skill_xp",
			name = "Skill XP",
			description = "Sends live XP per skill as it is gained, instead of waiting for the OSRS hiscores to catch up",
			section = entitiesSection,
			position = 211
	)
	default boolean skillXp() {
		return false;
	}

	@ConfigItem(
			keyName = "inventory",
			name = "Inventory",
			description = "Sends the items in your inventory and how many slots are free",
			section = entitiesSection,
			position = 214
	)
	default boolean sendInventory() {
		return false;
	}

	@ConfigItem(
			keyName = "equipment",
			name = "Equipment",
			description = "Sends the items you are wearing, per equipment slot",
			section = entitiesSection,
			position = 215
	)
	default boolean sendEquipment() {
		return false;
	}

	@ConfigItem(
			keyName = "activity",
			name = "Activity",
			description = "Sends which skill you are working on, read from your animation (mining, fishing, woodcutting, ...)",
			section = entitiesSection,
			position = 216
	)
	default boolean sendActivity() {
		return false;
	}

	/*
		Events section
	 */

	@ConfigItem(
			keyName = "send_collection_log_events",
			name = "Collection log events",
			description = "Sends events when receiving a collection log",
			section = eventsSection,
			position = 301
	)
	default boolean sendCollectionLogEvents() {
		return true;
	}

	@ConfigItem(
			keyName = "send_combat_task_events",
			name = "Combat task events",
			description = "Sends events when receiving completing a combat task",
			section = eventsSection,
			position = 302
	)
	default boolean sendCombatTaskEvents() {
		return true;
	}

	@ConfigItem(
			keyName = "send_diary_events",
			name = "Achievement diary events",
			description = "Sends events when completing an achievement diary",
			section = eventsSection,
			position = 303
	)
	default boolean sendDiaryEvents() {
		return true;
	}

	@ConfigItem(
			keyName = "send_quest_complete_events",
			name = "Quest complete events",
			description = "Sends an event when a quest is completed",
			section = eventsSection,
			position = 304
	)
	default boolean sendQuestCompleteEvents() {
		return false;
	}

	@ConfigItem(
			keyName = "send_idle_events",
			name = "Idle events",
			description = "Sends events when you go idle",
			section = eventsSection,
			position = 305
	)
	default boolean sendIdleEvents() {
		return true;
	}
	@ConfigItem(
			keyName = "idle_tick_delay",
			name = "Idle delay (ticks)",
			description = "Updates once you've been idle for x ticks",
			section = eventsSection,
			position = 306
	)
	default int idleTickDelay() {
		return 50;
	}

	@ConfigItem(
			keyName = "varbit_ids_event",
			name = "Watch VarBit ID",
			description = "Send event when Varbit ID changes, comma seperated numbers",
			section = eventsSection,
			position = 307
	)
	default String varbitIdsEvent()
	{
		return "";
	}

	@ConfigItem(
			keyName = "varbit_ids_event_info",
			name = "You can find the Varbit ID's in the runelite docs",
			description = "https://github.com/runelite/runelite/blob/master/runelite-api/src/main/java/net/runelite/api/gameval/VarbitID.java",
			section = eventsSection,
			position = 308
	)
	default void varbitInfo() {}


	/*
		Miscellaneous section
	 */

	@ConfigItem(
			keyName = "ignorefarmingguild",
			name = "Ignore Farming Guild",
			description = "Ignore patches in the farming guild when determining the next update.",
			section = miscellaneousSection,
			position = 401
	)
	default boolean ignoreFarmingGuild() {
		return true;
	}

	@ConfigItem(
			keyName = "farming_tick_offset",
			name = "Farming tick offset",
			description = "Tick offsets are account specific, this will automatically update it in homeassistant.",
			section = miscellaneousSection,
			position = 402
	)
	default boolean farmingTickOffset() {
		return true;
	}

	@ConfigItem(
			keyName = "aggression_timer_delay",
			name = "Aggression timer delay (ticks)",
			description = "Only updates the aggression timer every x ticks.",
			section = miscellaneousSection,
			position = 403
	)
	default int aggressionTimerDelay() {
		return 50;
	}

	@ConfigItem(
			keyName = "global_update_throttle",
			name = "Global tick throttle",
			description = "Only updates homeassistant every x ticks. 0 for every tick",
			section = miscellaneousSection,
			position = 404
	)
	default int globalUpdateThrottle() {
		return 0;
	}

	/*
		Debug section
	 */

	@ConfigItem(
			keyName = "test_collection_log_event",
			name = "Test clog event",
			description = "Sends a test collection log request to your homeassistant",
			section = DebugSection,
			position = 501
	)
	default boolean testCollectionLogEvent() {
		return false;
	}

	@ConfigItem(
			keyName = "test_combat_task_event",
			name = "Test combat task event",
			description = "Sends a test combat task request to your homeassistant",
			section = DebugSection,
			position = 502
	)
	default boolean testCombatTaskEvent() {
		return false;
	}

	@ConfigItem(
			keyName = "test_diary_event",
			name = "Test achievement diary event",
			description = "Sends a test diary completion request to your homeassistant",
			section = DebugSection,
			position = 503
	)
	default boolean testDiaryEvent() {
		return false;
	}

	@ConfigItem(
			keyName = "test_quest_complete_event",
			name = "Test quest complete event",
			description = "Sends a test quest complete event to your homeassistant",
			section = DebugSection,
			position = 504
	)
	default boolean testQuestCompleteEvent() {
		return false;
	}

	@ConfigItem(
			keyName = "aggression_area",
			name = "Show aggression area and timer",
			description = "Shows edge tiles of the 2 aggression squares",
			section = DebugSection,
			position = 505
	)
	default boolean aggressionShowArea() {
		return false;
	}

}

package com.homeassistant;

import com.google.gson.Gson;
import com.google.inject.Provides;
import javax.inject.Inject;

import com.homeassistant.classes.Utils;
import com.homeassistant.overlays.AggressionOverlay;
import com.homeassistant.trackers.*;
import com.homeassistant.trackers.FarmingTracker;
import com.homeassistant.trackers.events.HomeassistantEvents;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import okhttp3.*;

import java.io.IOException;
import java.util.*;

@Slf4j
@PluginDescriptor(
	name = "Homeassistant"
)
public class HomeassistantPlugin extends Plugin
{
	private final boolean DEBUG_15_TICK = false;
	private int DEBUG_CURRENT = 0;

	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private HomeassistantConfig config;
	@Inject
	private Gson gson;
	@Inject
	private OkHttpClient okHttpClient;
	@Inject
	private EventBus eventBus;
	@Inject
	private AggressionTracker aggressionTracker;
	@Inject
	private PlayerDataTracker playerDataTracker;
	@Inject
	private DailyTracker dailyTracker;
	@Inject
	private FarmingTracker farmingTracker;
	@Inject
	private BirdhouseTracker  birdhouseTracker;
	@Inject
	private CollectionTracker collectionTracker;
	@Inject
	private CombatTaskTracker combatTaskTracker;
	@Inject
	private AchievementDiaryTracker  achievementDiaryTracker;
	@Inject
	private IdleTracker idleTracker;
	@Inject
	private VarbitTracker varbitTracker;

	@Inject
	private SlayerTracker slayerTracker;
	@Inject
	private QuestTracker questTracker;
	@Inject
	private InventoryTracker inventoryTracker;
	@Inject
	private ActivityTracker activityTracker;
	@Inject
	private AggressionOverlay aggressionOverlay;
	@Inject
	OverlayManager overlayManager;

	private final Map<String,Map<String, Object>> updateSortedEntities = new HashMap<>();

	private int currentDelayCount = -5;

	@Override
	protected void startUp() throws Exception
	{
		log.debug("Homeassistant started!");
		currentDelayCount = -5;
		updateSortedEntities.clear();
		registerTrackers();

		overlayManager.add(aggressionOverlay);
	}

	private void registerTrackers(){
		eventBus.register(playerDataTracker);
		eventBus.register(aggressionTracker);
		eventBus.register(dailyTracker);
		eventBus.register(farmingTracker);
		eventBus.register(birdhouseTracker);
		eventBus.register(collectionTracker);
		eventBus.register(achievementDiaryTracker);
		eventBus.register(combatTaskTracker);
		eventBus.register(idleTracker);
		eventBus.register(varbitTracker);
		eventBus.register(slayerTracker);
		eventBus.register(questTracker);
		eventBus.register(inventoryTracker);
		eventBus.register(activityTracker);
	}

	@Override
	protected void shutDown() throws Exception
	{
		eventBus.unregister(playerDataTracker);
		eventBus.unregister(aggressionTracker);
		eventBus.unregister(dailyTracker);
		eventBus.unregister(farmingTracker);
		eventBus.unregister(birdhouseTracker);
		eventBus.unregister(collectionTracker);
		eventBus.unregister(achievementDiaryTracker);
		eventBus.unregister(combatTaskTracker);
		eventBus.unregister(idleTracker);
		eventBus.unregister(slayerTracker);
		eventBus.unregister(questTracker);
		eventBus.unregister(inventoryTracker);
		eventBus.unregister(activityTracker);
		eventBus.unregister(varbitTracker);

		overlayManager.remove(aggressionOverlay);
		log.info("Homeassistant stopped!");
	}


	@Provides
	HomeassistantConfig provideConfig(ConfigManager configManager)
	{
        return configManager.getConfig(HomeassistantConfig.class);
	}

/*
	This event can be called from any tracker. It will overwrite any previous object with the same entity_id. So if a throttle is active it will always update the latest
	getEntities() returns List<Map<String, Object>>
 */
	@Subscribe
	public void onUpdateEntities(HomeassistantEvents.UpdateEntities event){
		for(Map<String, Object> map : event.getEntities()){
			if(map.containsKey("entity_id")){
				String entityId = (String) map.get("entity_id");
				updateSortedEntities.put(entityId, map);
			}
		}
		log.info("update entities received, total: {}", updateSortedEntities);
	}
	/**
	 * This event can be called from any tracker. IT will immediately send a request to homeassistant, for example when a collection log notification is sent.
	 * `String getService()` returns name of the service in homeassistant, this is everything after domain/api/services/runelite/
	 * `Map<String, Object> getEventObj()` data to be serialized and sent to homeassistant
     */
	@Subscribe
	public void onSendEvent(HomeassistantEvents.SendEvent event){
		log.info("send event:{}, {}", event.getService(), event.getEventObj());
		sendEventToHomeAssistant(event.getService(), event.getEventObj());
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		String group = event.getGroup();
		if (!group.equals(HomeassistantConfig.CONFIG_GROUP)) {
			return;
		}
		if (event.getKey().equals("validate_token") && config.validateToken())
		{
			testHomeAssistant();
        }
	}

	@Subscribe
	public void onGameTick(GameTick event){
		if(DEBUG_15_TICK && DEBUG_CURRENT < 15){
			DEBUG_CURRENT++;

			if(DEBUG_CURRENT == 15){
				runDebug15Tick();
			}
		}
		// If the user has a global throttled setup, it will only update once every x ticks
		currentDelayCount++;
		if(currentDelayCount >= config.globalUpdateThrottle()){
			currentDelayCount = 0;
			if(Utils.GetUserName(client) != null && !updateSortedEntities.isEmpty()){
				log.debug("Updating sorted entities: {}", updateSortedEntities);
				List<Map<String, Object>> entities = new ArrayList<>();
				for(Map.Entry<String, Map<String, Object>> entry : updateSortedEntities.entrySet()){
					entities.add(entry.getValue());
				}

				Map<String, Object> payload = new HashMap<>();
				payload.put("entities", entities);

				Gson gson = this.gson.newBuilder().create();
				String jsonPayload = gson.toJson(payload);

				updateSortedEntities.clear();

				sendPayloadToHomeAssistant(jsonPayload);
			}
		}
	}

	private void sendEventToHomeAssistant(String service, Map<String, Object> event){
		Gson gson = this.gson.newBuilder().create();
		String jsonPayload = gson.toJson(event);

		sendPayloadToHomeAssistant(jsonPayload, String.format("/services/runelite/%s", service));
	}

	private void sendPayloadToHomeAssistant(String jsonPayload) {
		sendPayloadToHomeAssistant(jsonPayload, "/services/runelite/set_multi_entity_data");
	}

	private void sendPayloadToHomeAssistant(String jsonPayload, String url) {
		String homeAssistantUrl = config.homeassistantUrl();
		String accessToken = config.homeassistantToken();

		if (homeAssistantUrl.isEmpty() || accessToken.isEmpty()) {
			log.warn("Home Assistant URL or Access Token not configured.");
			return;
		}

		String apiUrl = homeAssistantUrl + "/api" + url;
		RequestBody requestBody = RequestBody.create(MediaType.parse("application/json; charset=utf-8"), jsonPayload);
		log.debug("Sending payload to home assistant, {}: {}", apiUrl, jsonPayload);
		Request request = new Request.Builder()
				.url(Objects.requireNonNull(HttpUrl.parse(apiUrl)))
				.header("Authorization", "Bearer " + accessToken)
				.header("Content-Type", "application/json")
				.post(requestBody)
				.build();

		okHttpClient.newCall(request).enqueue(new Callback() {
			@Override
			public void onFailure(Call call, IOException e) {
				log.error("Error submitting the entity to homeassistant ", e);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException {
				log.info("Successfully created/updated entity {}.", jsonPayload);
				response.close();
			}
		});
	}

	private void testHomeAssistant()
	{
		String homeAssistantUrl = config.homeassistantUrl();
		String accessToken = config.homeassistantToken();


		if (homeAssistantUrl.isEmpty() || accessToken.isEmpty())
		{
			log.warn("Home Assistant URL or Access Token not configured.");
			return;
		}

		String apiUrl = homeAssistantUrl + "/api/";

		Request request = new Request.Builder()
				.url(Objects.requireNonNull(HttpUrl.parse(apiUrl)))
				.header("Authorization", "Bearer " + accessToken)
				.get()
				.build();

		log.info("Testing Home Assistant connection with URL: {}", apiUrl);

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.error("Error connecting to the Home Assistant API", e);
				clientThread.invoke(() -> client.addChatMessage(
					ChatMessageType.GAMEMESSAGE,
					"",
					"Invalid Home Assistant token or URL.",
					null
				));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				int code  = response.code();
				String message = response.message();
				if(code != 200){
					clientThread.invoke(() -> client.addChatMessage(
						ChatMessageType.GAMEMESSAGE,
						"",
							String.format("Invalid Home Assistant token or URL. Code: %s, message: %s", code, message),
						null
					));
				} else {
					clientThread.invoke(() -> client.addChatMessage(
						ChatMessageType.GAMEMESSAGE,
						"",
						"Home Assistant token and URL are valid.",
						null
					));

					String apiUrl = homeAssistantUrl + "/api/services";

					Request request = new Request.Builder()
							.url(Objects.requireNonNull(HttpUrl.parse(apiUrl)))
							.header("Authorization", "Bearer " + accessToken)
							.get()
							.build();

					log.info("Listing home assistant services: {}", apiUrl);
					okHttpClient.newCall(request).enqueue(new Callback()
					{
						@Override
						public void onFailure(Call call, IOException e)
						{
							log.error("Error listing home assistant services", e);
							clientThread.invoke(() -> client.addChatMessage(
									ChatMessageType.GAMEMESSAGE,
									"",
									"Could not list home assistant services",
									null
							));
						}

						@Override
						public void onResponse(Call call, Response response)
						{
							int code  = response.code();
							String message = response.message();
							if(code != 200){
								clientThread.invoke(() -> client.addChatMessage(
										ChatMessageType.GAMEMESSAGE,
										"",
										String.format("Could not list home assistant services. Code: %s, message: %s", code, message),
										null
								));
							} else {
								log.info("Successfully listed home assistant services.");
								try {
									String responseBody = response.body().string();
									List<Map<String, Object>> services = gson.fromJson(responseBody, List.class);
									Set<String> domains = new HashSet<>();
									for (Map<String, Object> service : services) {
										domains.add((String) service.get("domain"));
									}
									log.info("Available service domains: {}", domains);
									if (!domains.contains("runelite")) {
										clientThread.invoke(() -> client.addChatMessage(
											ChatMessageType.GAMEMESSAGE,
											"",
											"Warning: 'runelite' service domain not found in Home Assistant",
											null
										));

										clientThread.invoke(() -> client.addChatMessage(
											ChatMessageType.GAMEMESSAGE,
											"",
											"To make this plugin work, please add the 'runelite' integration to Home Assistant, more information in this plugin's GitHub repository.",
											null
										));
									} else {
										clientThread.invoke(() -> client.addChatMessage(
											ChatMessageType.GAMEMESSAGE,
											"",
											"Successfully found the runelite plugin",
											null
										));

									}
								} catch (Exception e) {
									log.error("Error parsing Home Assistant services response", e);
								}
							}
							response.close();
						}
					});
				}
				response.close();
			}
		});
	}

	public void runDebug15Tick(){
		log.debug("Debug 15 Tick");
	}
