import java.util.Objects;

public class StatusEffect {
    public String name;
    public int number = 0;
    public String time = "";

    public StatusEffect copy(){
        StatusEffect copy = new StatusEffect();
        copy.name = name;
        copy.number = number;
        copy.time = time;
        return copy;
    }

    @Override
    public boolean equals(Object o)
    {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;

        StatusEffect that = (StatusEffect) o;
        return number == that.number &&
                Objects.equals(name, that.name) &&
                Objects.equals(time, that.time);
    }

    @Override
    public int hashCode()
    {
        return Objects.hash(name, number, time);
    }
}

package com.homeassistant.classes;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;

import java.util.Objects;

@Slf4j
public  class Utils {
    public static String GetUserName(Client client){

        try {
            String slug = Objects.requireNonNull(client.getLocalPlayer().getName()).toLowerCase();

            // Replace all non a-z, 0-9, or _ with _
            slug = slug.replaceAll("[^a-z0-9_]", "_");

            // Collapse multiple underscores into one
            slug = slug.replaceAll("_+", "_");

            // Remove leading/trailing underscores
            slug = slug.replaceAll("^_+|_+$", "");
            return slug;
        } catch (NullPointerException e) {
            log.error("Error fetching username: {}", e.getMessage());
            return null;
        }
    }
}

