            log.debug("Aggression config missing; nothing to load");
            return;
        }

        // Reconstruct saved tiles
        if (x1Long != null && y1Long != null)
        {
            tile1 = new WorldPoint(x1Long.intValue(), y1Long.intValue(), currentLocation.getPlane());
        }
        if (x2Long != null && y2Long != null)
        {
            tile2 = new WorldPoint(x2Long.intValue(), y2Long.intValue(), currentLocation.getPlane());
        }

        int savedTicks = ticksLong != null ? ticksLong.intValue() : 0;

        // Measure distance to see if we are still in the same zone
        int distanceFromTile1 = getDistance(currentLocation, tile1);
        int distanceFromTile2 = getDistance(currentLocation, tile2);

        if (distanceFromTile1 < RESET_DISTANCE || distanceFromTile2 < RESET_DISTANCE)
        {
            // Still in same zone
            if (savedTicks <= 0)
            {
                log.debug("Previously expired and still in same zone. Staying inactive.");
                ticksLeft = 0;
                active = false;
                initialized = true;
                isLoaded = true;
                return;
            }
            else
            {
                log.debug("Aggression timer still valid. Resuming from saved state.");
                ticksLeft = savedTicks;
                initialized = true;
                isLoaded = true;
                return;
            }
        }
        else
        {
            log.debug("Logged in outside saved area. Staying inactive until movement resets aggression.");
            aggroEnded();
            previousUnknownCenter = currentLocation;
            isLoaded = true;
            return;
        }
    }


    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (!config.aggressionTimer())
        {
            return;
        }

        Player player = client.getLocalPlayer();
        if (player == null || client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        WorldPoint currentLocation = player.getWorldLocation();

        if(currentLocation == null){
            log.debug("Aggression config missing; nothing to load");
            return;
        }



        if (!isLoaded)
        {
            loadFromConfig();

            // If we still failed to load config, and nothing is initialized, start tracking movement
            if (!isLoaded && !initialized && previousUnknownCenter == null)
            {
                previousUnknownCenter = player.getWorldLocation();
                log.debug("Aggression config not loaded. Tracking movement from {}", previousUnknownCenter);
                isLoaded = true;
                return;
            }
        }

        if (previousUnknownCenter != null)
        {
            int distance = getDistance(currentLocation, previousUnknownCenter);

            if (distance >= RESET_DISTANCE * 2)
            {
                log.debug("Moved far from unknown center ({} tiles). Starting new aggression zone.", distance);
                startNewAggressionZone(currentLocation);
                previousUnknownCenter = null;
            }else{
                previousUnknownCenter = currentLocation;
            }
            return;
        }

        if(!initialized){
            return;
        }

        int dist1 = getDistance(currentLocation, tile1);
        int dist2 = getDistance(currentLocation, tile2);

        if (previousFiredEvent > 0)
        {
            previousFiredEvent--;
        }

        if (dist1 >= RESET_DISTANCE && dist2 >= RESET_DISTANCE)
        {
            resetAggroTimer(currentLocation);
        }
        else
        {
            if (ticksLeft > 0)
            {
                ticksLeft--;
                if (previousFiredEvent == 0 && ticksLeft > 0)
                {
                    aggroTick();
                }

                if (ticksLeft == 0)
                {
                    aggroEnded();
                }
            }
        }
    }

    private void startNewAggressionZone(WorldPoint center)
    {
        tile1 = center;
        tile2 = center;
        ticksLeft = AGGRESSION_TIMEOUT_TICKS;
        active = true;
        wasActive = true;
        initialized = true;

        saveToConfig();
        log.debug("Started new aggression zone at {}", center);
    }


    private void aggroTick()
    {
        previousFiredEvent = config.aggressionTimerDelay();

        List<Map<String, Object>> entities = new ArrayList<>();
        active = true;
        wasActive = true;

        int seconds = (int) (ticksLeft * 0.6f);

        String entityId = String.format("sensor.runelite_%s_aggression", Utils.GetUserName(client));
        Map<String, Object> attributes = new HashMap<>();
        attributes.put("entity_id", entityId);
        attributes.put("status", AggressionStatus.ACTIVE.getId());
        attributes.put("seconds", seconds);
        attributes.put("ticks", ticksLeft);
        entities.add(attributes);

        eventBus.post(new HomeassistantEvents.UpdateEntities(entities));
    }

    private void aggroEnded()
    {
        previousFiredEvent = config.aggressionTimerDelay();
        active = false;

        List<Map<String, Object>> entities = new ArrayList<>();

        String entityId = String.format("sensor.runelite_%s_aggression", Utils.GetUserName(client));
        Map<String, Object> attributes = new HashMap<>();
        attributes.put("entity_id", entityId);
        attributes.put("status", AggressionStatus.SAFE.getId());
        attributes.put("seconds", 0);
        attributes.put("ticks", 0);
        entities.add(attributes);

        eventBus.post(new HomeassistantEvents.UpdateEntities(entities));
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (!config.aggressionTimer())
        {
            return;
        }

        GameState state = event.getGameState();
        if (state == GameState.HOPPING || state == GameState.LOGIN_SCREEN)
        {
            saveToConfig();
            isLoaded = false;
        }
    }

    private void initialize(WorldPoint loc)
    {
        tile1 = loc;
        tile2 = loc;
        ticksLeft = AGGRESSION_TIMEOUT_TICKS;
        active = false;
        wasActive = false;
        initialized = true;
    }

    private void resetAggroTimer(WorldPoint newLocation)
    {
        boolean wasActiveBefore = active;

        tile1 = tile2;
        tile2 = newLocation;

        ticksLeft = AGGRESSION_TIMEOUT_TICKS;
        active = false;
        wasActive = false;

        if (wasActiveBefore)
        {
            log.debug("Aggression timer reset from movement.");
        }
    }

    private void reset()
    {
        ticksLeft = 0;
        active = false;
        wasActive = false;
        tile1 = null;
        tile2 = null;
        initialized = false;
    }

    private int getDistance(WorldPoint a, WorldPoint b)
    {
        if (a == null || b == null || a.getPlane() != b.getPlane())
        {
            return Integer.MAX_VALUE;
        }
        return a.distanceTo(b);
    }
}

package com.homeassistant.trackers;

import com.homeassistant.HomeassistantConfig;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.EventBus;

import javax.inject.Inject;
import java.util.ArrayList;
import java.util.List;

public abstract class BaseTracker {
    protected final Client client;
    protected final EventBus eventBus;
    protected final HomeassistantConfig config;
    protected final VarbitTracker varbitTracker;

    @Inject
    public BaseTracker(Client client, EventBus eventBus, HomeassistantConfig config, VarbitTracker varbitTracker) {
        this.client = client;
        this.eventBus = eventBus;
        this.config = config;
        this.varbitTracker = varbitTracker;

        this.eventBus.register(this.varbitTracker);
    }

    // Optional: subclasses can override if they want to track varbits
    protected String getVarbitTrackerId() {
        return null;
    }

    protected List<Integer> getTrackedVarbits() {
        return List.of(); // empty list by default
    }

    public void setVarbitTracker(boolean active) {
        this.setVarbitTracker(active, null);
    }

    public void setVarbitTracker(boolean active, Integer overrideValue) {
        String id = getVarbitTrackerId();
        List<Integer> varbits = getTrackedVarbits();

        if (id == null || varbits == null || varbits.isEmpty()) {
            return; // this subclass doesn't use varbit tracking
        }

        if (active) {
            varbitTracker.setInternalWatch(id, varbits, overrideValue);
        } else {
            varbitTracker.setInternalWatch(id, new ArrayList<>(), overrideValue);
        }
    }
}

package com.homeassistant.trackers;

import java.time.Instant;
import java.util.*;

import com.homeassistant.HomeassistantConfig;

import com.homeassistant.classes.Utils;
import com.homeassistant.enums.PatchStatus;
import com.homeassistant.runelite.hunter.BirdHouseTracker;
import com.homeassistant.trackers.events.HomeassistantEvents;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.timetracking.TimeTrackingConfig;

import javax.inject.Inject;
import javax.inject.Singleton;

@Slf4j
@Singleton
public class BirdhouseTracker {

    private final EventBus eventBus;
    private final Client client;
    private final HomeassistantConfig config;
    private final ConfigManager configManager;
    private final ItemManager itemManager;
    private final Notifier notifier;

    private BirdHouseTracker birdHouseTracker;

    private long birdhouseCompletionTime = -2L;
    private long previousBirdhouseCompletionTime = -2L;
    private boolean hasChecked = false;

    @Inject
    public BirdhouseTracker(
            EventBus eventBus,
            Client client,
            HomeassistantConfig config,
            ConfigManager configManager,
            ItemManager itemManager,
            Notifier notifier
    ) {
        this.eventBus = eventBus;
        this.client = client;
        this.config = config;
        this.configManager = configManager;
        this.itemManager = itemManager;
        this.notifier = notifier;
        reset();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged gameStateChanged) {
        if(!config.birdHouses()){
            return;
        }
        GameState gameState = gameStateChanged.getGameState();

        if (gameState != GameState.LOGGED_IN){
            return;
        }

        checkAll();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if(!config.birdHouses()){
            return;
        }
        String group = event.getGroup();
        if (!group.equals(TimeTrackingConfig.CONFIG_GROUP) && !group.equals(HomeassistantConfig.CONFIG_GROUP)) {
            return;
        }

        checkAll();
    }

    @Subscribe
    public void onGameTick(GameTick event){
        if(!config.birdHouses()){
            return;
        }
        if(!hasChecked && Utils.GetUserName(client) != null){
            hasChecked = true;
            checkAll();
        }
    }

    private void checkAll() {
        if(Utils.GetUserName(client) == null || !config.birdHouses()){
            hasChecked = false;
            return;
        }

        birdHouseTracker.loadFromConfig();
        birdhouseCompletionTime = birdHouseTracker.getCompletionTime();

        List<Map<String, Object>> entities = new ArrayList<>();
        if (previousBirdhouseCompletionTime != birdhouseCompletionTime) {
            String entityId = generateBirdhouseEntityId();
            if (entityId != null) {
                Map<String, Object> attributes = new HashMap<>();
                attributes.put("entity_id", entityId);
                attributes.put("status", PatchStatus.IN_PROGRESS.getName());
                attributes.put("completion_time", Instant.ofEpochSecond(birdhouseCompletionTime).toString());

                entities.add(attributes); // ✅ add to array
                previousBirdhouseCompletionTime = birdhouseCompletionTime;
            }
        }
        resetPrevious();

        if(entities.isEmpty()){
            return;
        }

        eventBus.post(new HomeassistantEvents.UpdateEntities(entities));
    }

    private void reset() {
        birdhouseCompletionTime = -1L;
        resetPrevious();

        TimeTrackingConfig timeTrackingConfig = configManager.getConfig(TimeTrackingConfig.class);

        birdHouseTracker = new BirdHouseTracker(
                client,
                itemManager,
                configManager,
                timeTrackingConfig,
                notifier
        );
    }

    private void resetPrevious() {
        previousBirdhouseCompletionTime = birdhouseCompletionTime;
    }

    private String generateBirdhouseEntityId() {
        try{
            return String.format("sensor.runelite_%s_birdhouses", Utils.GetUserName(client));
        }catch (NullPointerException e){
            log.error("Error generating entity id for birdhouses: {}", e.getMessage());
            return null;
        }

    }
}

package com.homeassistant.trackers;

import com.homeassistant.HomeassistantConfig;
import com.homeassistant.trackers.events.HomeassistantEvents;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.timetracking.TimeTrackingConfig;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.Map;

@Slf4j
@Singleton
public class CollectionTracker {
    private final HomeassistantConfig config;
    private final EventBus eventBus;

    private boolean currentSendTestRequest = false;

    @Inject
    public CollectionTracker(EventBus eventBus, HomeassistantConfig config)
    {
        this.eventBus = eventBus;
        this.config = config;

        this.currentSendTestRequest = config.testCollectionLogEvent();
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if(!config.sendCollectionLogEvents()) return;
        if (event.getType() != ChatMessageType.GAMEMESSAGE) return;

        String msg = Text.removeTags(event.getMessage());
        String prefix = "New item added to your collection log:";
        if (msg.startsWith(prefix)) {
            String item = msg.substring(prefix.length()).trim();
            log.debug("Detected collection log unlock: {}", item);

            Map<String, Object> thisEvent = new HashMap<>();
            thisEvent.put("item_name", item);
            eventBus.post(new HomeassistantEvents.SendEvent(thisEvent, "trigger_collection_log_notify"));
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        String group = event.getGroup();
        if (!group.equals(HomeassistantConfig.CONFIG_GROUP)) {
            return;
        }

        if(!currentSendTestRequest && config.testCollectionLogEvent()) {
            currentSendTestRequest = true;

            Map<String, Object> thisEvent = new HashMap<>();
            thisEvent.put("item_name", "Test Item");
            eventBus.post(new HomeassistantEvents.SendEvent(thisEvent, "trigger_collection_log_notify"));
        }else{
            currentSendTestRequest = config.testCollectionLogEvent();
        }
    }
}

package com.homeassistant.trackers;

import com.homeassistant.HomeassistantConfig;
import com.homeassistant.trackers.events.HomeassistantEvents;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
@Singleton
public class CombatTaskTracker {

    private final HomeassistantConfig config;
    private final EventBus eventBus;
    private final ClientThread  clientThread;
    private final Client client;

    private boolean currentSendTestRequest;

    private static final Pattern COMBAT_TASK_PATTERN = Pattern.compile(
            "Congratulations, you've completed an? (?<tier>easy|medium|hard|elite|master|grandmaster) combat task:(?<task>.+?)",
            Pattern.CASE_INSENSITIVE
    );

    @Inject
    public CombatTaskTracker(EventBus eventBus, HomeassistantConfig config, Client client, ClientThread clientThread) {
        this.eventBus = eventBus;
        this.config = config;
        this.client = client;
        this.clientThread = clientThread;

        this.currentSendTestRequest = config.testCombatTaskEvent();
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (!config.sendCombatTaskEvents()) return;
        if (event.getType() != ChatMessageType.GAMEMESSAGE) return;

        String msg = Text.removeTags(event.getMessage());
        Matcher matcher = COMBAT_TASK_PATTERN.matcher(msg);

        if (matcher.matches()) {
            String task = matcher.group("task");
            String tier = matcher.group("tier");

            log.debug("Detected combat task completion: {} (tier: {})", task, tier);

            Map<String, Object> thisEvent = new HashMap<>();
            thisEvent.put("task_name", task);
            thisEvent.put("tier", tier);
            eventBus.post(new HomeassistantEvents.SendEvent(thisEvent, "trigger_combat_task_notify"));
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!event.getGroup().equals(HomeassistantConfig.CONFIG_GROUP)) return;

        if (!currentSendTestRequest && config.testCombatTaskEvent()) {
            currentSendTestRequest = true;

            clientThread.invoke(() -> client.addChatMessage(
                    ChatMessageType.GAMEMESSAGE,
                    "",
                    "Congratulations, you've completed an easy combat task: <col=06600c>A Slow Death</col> (1 point).",
                    null
            ));

        } else {
            currentSendTestRequest = config.testCombatTaskEvent();
        }
    }
}

package com.homeassistant.trackers;

import java.util.*;

import com.homeassistant.HomeassistantConfig;
import com.homeassistant.classes.Utils;
import com.homeassistant.enums.DailyTask;

import com.homeassistant.trackers.events.HomeassistantEvents;
import com.homeassistant.trackers.events.InternalEvents;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;

import javax.inject.Inject;
import javax.inject.Singleton;

@Slf4j
@Singleton
public class DailyTracker extends BaseTracker {
    protected final String TRACKER_ID = "dailyTracker";
    protected final List<Integer> TRACKED_VARBITS = List.of(
        VarbitID.NZONE_HERBBOXES_PURCHASED,
        VarbitID.ZAFF_LAST_CLAIMED,
        VarbitID.ARDOUGNE_FREE_ESSENCE,
        VarbitID.LUNDAIL_LAST_CLAIMED,
        VarbitID.YANILLE_SAND_CLAIMED,
        VarbitID.SEERS_FREE_FLAX,
        VarbitID.WESTERN_RANTZ_ARROWS,
        VarbitID.KOUREND_FREE_DYNAMITE
    );
    private static final int HERB_BOX_MAX = 15;
    private static final int HERB_BOX_COST = 9500;
    private static final int SAND_QUEST_COMPLETE = 160;

    private final Map<DailyTask, Integer> dailyStatuses = new EnumMap<>(DailyTask.class);
    private final Map<DailyTask, Integer> previousDailyStatuses = new EnumMap<>(DailyTask.class);

    @Inject
    public DailyTracker(Client client, EventBus eventBus, HomeassistantConfig config, VarbitTracker varbitTracker)
    {
        super(client, eventBus, config, varbitTracker);
        reset();
    }

    @Override
    protected String getVarbitTrackerId() {
        return TRACKER_ID;
    }

    @Override
    protected List<Integer> getTrackedVarbits() {
        return TRACKED_VARBITS;
    }

    @Subscribe
    public void onVarbitUpdate(InternalEvents.VarbitUpdate event) {
        if (Objects.equals(event.getTrackerId(), TRACKER_ID)){
            checkAll();
        }
    }

    private void reset(){
        dailyStatuses.clear();

        for (DailyTask tab : DailyTask.values()) {
            dailyStatuses.put(tab, -1);
        }

        resetPrevious();
        this.setVarbitTracker(config.dailies(), -1);
    }

    private void resetPrevious(){

        previousDailyStatuses.clear();
        for (DailyTask tab : DailyTask.values()) {
            previousDailyStatuses.put(tab, dailyStatuses.get(tab));
        }
    }

    private void checkAll() {
        if(!config.dailies()){
            return;
        }
        checkHerbBoxes();
        checkStaves();
        checkEssence();
        checkRunes();
        checkSand();
        checkFlax();
        checkArrows();
        checkDynamite();

        List<Map<String, Object>> entities = new ArrayList<>();
        if(config.dailies()) {
            try {
                dailyStatuses.forEach((name, status) -> {
                    if (!previousDailyStatuses.get(name).equals(status)) {
                        String entityId = generateDailyEntityId(name.getId());
                        if (entityId == null) {
                            return;
                        }

                        Map<String, Object> attributes = new HashMap<>();
                        attributes.put("entity_id", entityId);
                        attributes.put("state", status);
                        entities.add(attributes);
                    }
                });
                resetPrevious();
            } catch (Exception e) {
                log.error(e.getMessage());
            }
        }

        resetPrevious();

        if(entities.isEmpty()){
            return;
        }

        eventBus.post(new HomeassistantEvents.UpdateEntities(entities));
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!event.getGroup().equals(HomeassistantConfig.CONFIG_GROUP)) return;

        this.setVarbitTracker(config.dailies(), -1);
    }

    private void checkHerbBoxes()
    {
        if(client.getVarbitValue(VarbitID.IRONMAN) != 0 || client.getVarpValue(VarPlayerID.NZONE_REWARDPOINTS) < HERB_BOX_COST){
            dailyStatuses.put(DailyTask.HERB_BOXES, -1);
            return;
        }

        if (client.getVarbitValue(VarbitID.NZONE_HERBBOXES_PURCHASED) < HERB_BOX_MAX)
        {
            dailyStatuses.put(DailyTask.HERB_BOXES, 0);
        } else {
            dailyStatuses.put(DailyTask.HERB_BOXES, 1);
        }
    }

    private void checkStaves()
    {
        if (client.getVarbitValue(VarbitID.VARROCK_DIARY_EASY_COMPLETE) != 1) {
            dailyStatuses.put(DailyTask.STAVES, -1);
            return;
        }

        if (client.getVarbitValue(VarbitID.ZAFF_LAST_CLAIMED) == 0) {
            dailyStatuses.put(DailyTask.STAVES, 0);
        } else {
            dailyStatuses.put(DailyTask.STAVES, 1);
        }
    }

    private void checkEssence()
    {
        if (client.getVarbitValue(VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE) != 1) {
            dailyStatuses.put(DailyTask.ESSENCE, -1);
            return;
        }

        if (client.getVarbitValue(VarbitID.ARDOUGNE_FREE_ESSENCE) == 0) {
            dailyStatuses.put(DailyTask.ESSENCE, 0);

        } else {
            dailyStatuses.put(DailyTask.ESSENCE, 1);
        }
    }

    private void checkRunes()
    {
        if(client.getVarbitValue(VarbitID.WILDERNESS_DIARY_EASY_COMPLETE) == 1){
            dailyStatuses.put(DailyTask.RUNES, -1);
            return;
        }

        if (client.getVarbitValue(VarbitID.LUNDAIL_LAST_CLAIMED) == 0) {
            dailyStatuses.put(DailyTask.RUNES, 0);
        } else {
            dailyStatuses.put(DailyTask.RUNES, 1);
        }
    }

    private void checkSand()
    {
        if (client.getVarbitValue(VarbitID.IRONMAN) == 2 /* UIM */
                || client.getVarbitValue(VarbitID.HANDSAND_QUEST) < SAND_QUEST_COMPLETE) {
            dailyStatuses.put(DailyTask.SAND, -1);
            return;
        }

        if (client.getVarbitValue(VarbitID.YANILLE_SAND_CLAIMED) == 0) {
            dailyStatuses.put(DailyTask.SAND, 0);
        } else {
            dailyStatuses.put(DailyTask.SAND, 1);
        }
    }

    private void checkFlax()
    {
        if (client.getVarbitValue(VarbitID.KANDARIN_DIARY_EASY_COMPLETE) != 1) {
            dailyStatuses.put(DailyTask.FLAX, -1);
            return;
        }

        if (client.getVarbitValue(VarbitID.SEERS_FREE_FLAX) == 0) {
            dailyStatuses.put(DailyTask.FLAX, 0);
        } else {
            dailyStatuses.put(DailyTask.FLAX, 1);
        }
    }

    private void checkArrows()
    {
        if (client.getVarbitValue(VarbitID.WESTERN_DIARY_EASY_COMPLETE) != 1) {
            dailyStatuses.put(DailyTask.ARROWS, -1);
            return;
        }

        if (client.getVarbitValue(VarbitID.WESTERN_RANTZ_ARROWS) == 0) {
            dailyStatuses.put(DailyTask.ARROWS, 0);
        } else {
            dailyStatuses.put(DailyTask.ARROWS, 1);
        }
    }

    private void checkDynamite()
    {
        if (client.getVarbitValue(VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE) == 1){
            dailyStatuses.put(DailyTask.DYNAMITE, -1);
            return;
        }

        if (client.getVarbitValue(VarbitID.KOUREND_FREE_DYNAMITE) == 0) {
            dailyStatuses.put(DailyTask.DYNAMITE, 0);
        } else {
            dailyStatuses.put(DailyTask.DYNAMITE, 1);
        }
    }

    private String generateDailyEntityId(String str){
        try {
            return String.format("sensor.runelite_%s_daily_%s", Utils.GetUserName(client), str.toLowerCase());
        }catch (NullPointerException e){
            log.error("Error generating entity id for daily {}: {}", str, e.getMessage());
            return null;
        }
    }
}

package com.homeassistant.trackers;

import java.time.Instant;
import java.util.*;

import com.homeassistant.HomeassistantConfig;

import com.homeassistant.classes.Utils;
import com.homeassistant.enums.PatchStatus;
import com.homeassistant.runelite.farming.*;
import com.homeassistant.trackers.events.HomeassistantEvents;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.timetracking.TimeTrackingConfig;

import javax.inject.Inject;
import javax.inject.Singleton;

@Slf4j
@Singleton
public class FarmingTracker {

    private com.homeassistant.runelite.farming.FarmingTracker farmingTracker;
    private FarmingContractManager farmingContractManager;
    private final EventBus eventBus;
    private final Client client;
    private final HomeassistantConfig config;
    private final ConfigManager configManager;
    private final ItemManager itemManager;
    private final Notifier notifier;
    private static final List<Tab> IGNORE_TABS = List.of(
            Tab.GRAPE,
            Tab.TIME_OFFSET,
            Tab.ANIMA,
            Tab.SPECIAL,
            Tab.BELLADONNA,
            Tab.CALQUAT,
            Tab.CELASTRUS,
            Tab.CRYSTAL,
            Tab.BIRD_HOUSE,
            Tab.OVERVIEW,
            Tab.HOPS,
            Tab.CLOCK
    );
    private int farmingTickOffset = 0;
    private int previousFarmingTickOffset = 0;

    private final Map<Tab, Long> farmingCompletionTimes = new EnumMap<>(Tab.class);
    private long farmingContractCompletionTime = -2L;
    private long previousFarmingContractCompletionTime = -2L;

    private final Map<Tab, Long> previousFarmingCompletionTimes = new EnumMap<>(Tab.class);
    private boolean hasChecked = false;

    @Inject
    public FarmingTracker(
            EventBus eventBus,
            Client client,
            HomeassistantConfig config,
            ConfigManager configManager,
            ItemManager itemManager,
            Notifier notifier
    ) {
        this.eventBus = eventBus;
        this.client = client;
        this.config = config;
        this.configManager = configManager;
        this.itemManager = itemManager;
        this.notifier = notifier;
        reset();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged gameStateChanged) {
        GameState gameState = gameStateChanged.getGameState();

        if (gameState != GameState.LOGGED_IN){
            return;
        }

        checkAll();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        String group = event.getGroup();
        if (!group.equals(TimeTrackingConfig.CONFIG_GROUP) && !group.equals(HomeassistantConfig.CONFIG_GROUP)) {
            return;
        }

        checkAll();
    }

    @Subscribe
    public void onGameTick(GameTick event){
        if(!hasChecked && Utils.GetUserName(client) != null){
            hasChecked = true;
            checkAll();
        }
    }

    private void checkEntities(){
        List<Map<String, Object>> entities = new ArrayList<>();

        try {
            // Farming Patches
            if(config.farmingPatches()) {
                for (Tab tab : Tab.values()) {
                    if (!Objects.equals(previousFarmingCompletionTimes.get(tab), farmingCompletionTimes.get(tab))) {
                        if(IGNORE_TABS.contains(tab)){
                            continue;
                        }
                        String entityId = generateFarmingPatchEntityId(tab);
                        if (entityId == null) continue;

                        Map<String, Object> attributes = new HashMap<>();
                        attributes.put("entity_id", entityId);

                        long completionTime = farmingCompletionTimes.get(tab);
                        PatchStatus patchStatus = PatchStatus.READY;

                        if (completionTime > 0) {
                            patchStatus = PatchStatus.IN_PROGRESS;
                            attributes.put("completion_time", Instant.ofEpochSecond(completionTime).toString());
                        } else if (completionTime == -1) {
                            patchStatus = PatchStatus.NEVER_PLANTED;
                        }

                        attributes.put("status", patchStatus.getName());

                        entities.add(attributes);
                        previousFarmingCompletionTimes.put(tab, farmingCompletionTimes.get(tab));
                    }
                }
            }

            // Farming Contract
            if(config.farmingContract()) {
                if (previousFarmingContractCompletionTime != farmingContractCompletionTime) {
                    String entityId = generateFarmingContractEntityId();
                    if (entityId != null) {

                        Map<String, Object> attributes = new HashMap<>();
                        attributes.put("entity_id", entityId);
                        attributes.put("status", PatchStatus.IN_PROGRESS.getName());
                        String contractName = farmingContractManager.getContractName();
                        Tab tab = farmingContractManager.getContractTab();
                        if (tab != null){
                            try {
                                attributes.put("patch_type", tab.name().toLowerCase());
                                attributes.put("crop_type", contractName);
                            }catch (NullPointerException e){
                                log.debug("Error getting contract name or tab: {}", e.getMessage());
                            }

                            log.info("Farming contract completion time: {}", farmingContractCompletionTime);
                            PatchStatus patchStatus = PatchStatus.READY;
                            if (farmingContractCompletionTime > 0) {
                                patchStatus = PatchStatus.IN_PROGRESS;
                                if(farmingContractCompletionTime == Long.MAX_VALUE){
                                    patchStatus = PatchStatus.OTHER;
                                } else {
                                    //				log.info("Farming contract completion time: {}", Instant.ofEpochSecond(completionTime).toString());
                                    attributes.put("completion_time", Instant.ofEpochSecond(farmingContractCompletionTime).toString());
                                }
                            }else if(farmingContractCompletionTime == -1){
                                patchStatus = PatchStatus.NEVER_PLANTED;
                            }
                            attributes.put("status", patchStatus.getName());

                            entities.add(attributes);
                            previousFarmingContractCompletionTime = farmingContractCompletionTime;
                        }
                    }
                }
            }
        } catch (Exception e){
            log.error(e.getMessage());
        }

        if(farmingTickOffset != previousFarmingTickOffset){
            Map<String, Object> farmingTickAttributes = new HashMap<>();
            farmingTickAttributes.put("entity_id", GenerateFarmingTickEntityId());
            farmingTickAttributes.put("farming_tick_offset", farmingTickOffset);

            entities.add(farmingTickAttributes);
        }

        resetPrevious();

        if(entities.isEmpty()){
            return;
        }

        eventBus.post(new HomeassistantEvents.UpdateEntities(entities));
    }


    private void checkAll() {
        if(Utils.GetUserName(client) == null){
            return;
        }

        resetPrevious();
        if(config.farmingPatches()) {
            farmingTracker.setIgnoreFarmingGuild(config.ignoreFarmingGuild());
            farmingTracker.loadCompletionTimes();
            for (Tab tab : Tab.values()) {
                if(IGNORE_TABS.contains(tab)){
                    continue;
                }
                farmingCompletionTimes.put(tab, farmingTracker.getCompletionTime(tab));
            }
        }

        if (config.farmingContract()) {
            farmingContractManager.loadContractFromConfig();
            farmingContractCompletionTime = farmingContractManager.getCompletionTime();
        }

        if(config.farmingTickOffset()) {
            int offset = configManager.getRSProfileConfiguration(TimeTrackingConfig.CONFIG_GROUP, TimeTrackingConfig.FARM_TICK_OFFSET, int.class);
            offset = offset * -1;

            if (offset != farmingTickOffset) {
                farmingTickOffset = offset;
            }
        }

        checkEntities();
    }

    public void reset(){
        TimeTrackingConfig timeTrackingConfig = configManager.getConfig(TimeTrackingConfig.class);
        FarmingWorld farmingWorld = new FarmingWorld();

        CompostTracker compostTracker = new CompostTracker(
                this.client,
                farmingWorld,
                this.configManager
        );

        PaymentTracker paymentTracker = new PaymentTracker(
                this.client,
                this.configManager,
                farmingWorld
        );

        farmingTracker = new com.homeassistant.runelite.farming.FarmingTracker(
                this.client,
                this.itemManager,
                this.configManager,
                timeTrackingConfig,
                farmingWorld,
                this.notifier,
                compostTracker,
                paymentTracker
        );
        farmingTracker.setIgnoreFarmingGuild(config.ignoreFarmingGuild());

        farmingContractManager = new FarmingContractManager(
                this.client,
                this.itemManager,
                this.configManager,
                timeTrackingConfig,
                farmingWorld,
                farmingTracker
        );

        for (Tab tab : Tab.values()) {
            if(IGNORE_TABS.contains(tab)){
                continue;
            }
            farmingCompletionTimes.put(tab, -2L);
        }
        farmingContractCompletionTime = -2L;
        farmingTickOffset = 0;
        hasChecked = false;

        resetPrevious();
    }

    public void resetPrevious(){
        for (Tab tab : Tab.values()) {
            if(IGNORE_TABS.contains(tab)){
                continue;
            }
            previousFarmingCompletionTimes.put(tab, farmingCompletionTimes.get(tab));
        }
        previousFarmingContractCompletionTime = farmingContractCompletionTime;
        previousFarmingTickOffset = farmingTickOffset;
    }



    private String generateFarmingPatchEntityId(Tab tab) {
        try {
            if(tab == Tab.BIG_COMPOST){
                return String.format("sensor.runelite_%s_compost_bin", Utils.GetUserName(client));
            }
            return String.format("sensor.runelite_%s_%s_patch", Utils.GetUserName(client), tab.name().toLowerCase());
        }catch (NullPointerException e){
            log.error("Error generating entity id for {}: {}", tab.name(), e.getMessage());
            return null;
        }
    }

    private String generateFarmingContractEntityId() {
        try{
            return String.format("sensor.runelite_%s_farming_contract", Utils.GetUserName(client));
        }catch (NullPointerException e){
            log.error("Error generating entity id for farming contract: {}", e.getMessage());
            return null;
        }
    }

    private String GenerateFarmingTickEntityId() {
        try{
            return String.format("sensor.runelite_%s_farming_tick_offset", Utils.GetUserName(client));
        }catch (NullPointerException e){
            log.error("Error generating entity id for farming tick offset: {}", e.getMessage());
            return null;
        }
    }
}

package com.homeassistant.trackers;

import com.homeassistant.HomeassistantConfig;
import com.homeassistant.trackers.events.HomeassistantEvents;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.PlayerDespawned;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashMap;
import java.util.Map;

@Slf4j
@Singleton
public class IdleTracker {
    private final HomeassistantConfig config;
    private final EventBus eventBus;
    private final Client client;

    private static final int IDLE_ANIMATION = -1;

    private int lastNonIdleTick = -1;
    private boolean sentEvent = false;

    @Inject
    public IdleTracker(EventBus eventBus, Client client, HomeassistantConfig config) {
        this.eventBus = eventBus;
        this.client = client;
        this.config = config;
        reset();
    }

    @Subscribe
    public void onGameTick(GameTick tick) {
        if (!config.sendIdleEvents()) return;

        Player player = client.getLocalPlayer();
        if (player == null) return;

        int animation = player.getAnimation();
        int pose = player.getPoseAnimation();
        int currentTick = client.getTickCount();

        // Consider player active if any of these are non-idle
        if (animation != IDLE_ANIMATION ||
                (pose != IDLE_ANIMATION && pose != player.getIdlePoseAnimation() )||
                player.getInteracting() != null) {
            // Only when we actually told Home Assistant the player went idle.
            // This branch runs on every active tick, so without the guard it
            // would fire continuously while the player is doing something.
            if (sentEvent) {
                log.debug("Player is active again after {} idle ticks", currentTick - lastNonIdleTick);

                Map<String, Object> activeData = new HashMap<>();
                activeData.put("idle_ticks", currentTick - lastNonIdleTick);

                eventBus.post(new HomeassistantEvents.SendEvent(activeData, "trigger_active_notify"));
            }

            lastNonIdleTick = currentTick;
            sentEvent = false; // allow idle event to fire again
            return;
        }

        // If enough time has passed, trigger idle
        if (isIdle() && !sentEvent) {
            log.debug("Player became idle, {}, {}", lastNonIdleTick, currentTick);
            sentEvent = true;

            Map<String, Object> idleData = new HashMap<>();
            idleData.put("idle_ticks", currentTick - lastNonIdleTick);

            eventBus.post(new HomeassistantEvents.SendEvent(idleData, "trigger_idle_notify"));
        }
    }


    private boolean isIdle() {
        return client.getTickCount() >= (lastNonIdleTick + config.idleTickDelay()) && lastNonIdleTick != -1;
    }

    @Subscribe
    public void onPlayerDespawned(PlayerDespawned event) {
        if (event.getPlayer() == client.getLocalPlayer()) {
            reset();
        }
    }

    private void reset() {
        lastNonIdleTick = -1;
        sentEvent = false;
    }
}

package com.homeassistant.trackers;

import com.homeassistant.HomeassistantConfig;
import com.homeassistant.classes.Utils;
import com.homeassistant.trackers.events.HomeassistantEvents;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

@Slf4j
@Singleton
public class InventoryTracker {
    private static final int INVENTORY_SLOTS = 28;

    private static final EquipmentInventorySlot[] WORN_SLOTS = {
            EquipmentInventorySlot.HEAD, EquipmentInventorySlot.CAPE,
            EquipmentInventorySlot.AMULET, EquipmentInventorySlot.WEAPON,
            EquipmentInventorySlot.BODY, EquipmentInventorySlot.SHIELD,
            EquipmentInventorySlot.LEGS, EquipmentInventorySlot.GLOVES,
            EquipmentInventorySlot.BOOTS, EquipmentInventorySlot.RING,
            EquipmentInventorySlot.AMMO,
    };

    private final HomeassistantConfig config;
    private final EventBus eventBus;
    private final Client client;
    private final ItemManager itemManager;

    private boolean inventoryDirty = false;
    private boolean equipmentDirty = false;
    private Map<String, Object> lastInventory = null;
    private Map<String, Object> lastEquipment = null;

    @Inject
    public InventoryTracker(EventBus eventBus, Client client, ItemManager itemManager,
                            HomeassistantConfig config) {
        this.eventBus = eventBus;
        this.client = client;
        this.itemManager = itemManager;
        this.config = config;
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event) {
        int id = event.getContainerId();
        if (id == InventoryID.INV) {
            inventoryDirty = true;
        } else if (id == InventoryID.WORN) {
            equipmentDirty = true;
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGGED_IN) {
            lastInventory = null;
            lastEquipment = null;
            inventoryDirty = true;
            equipmentDirty = true;
        }
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        if (!config.sendInventory() && !config.sendEquipment()) return;
        if (client.getGameState() != GameState.LOGGED_IN) return;

        String username = Utils.GetUserName(client);
        if (username == null) return;

        List<Map<String, Object>> entities = new ArrayList<>();

        if (inventoryDirty && config.sendInventory()) {
            inventoryDirty = false;
            Map<String, Object> inventory = readInventory(username);
            if (!Objects.equals(inventory, lastInventory)) {
                lastInventory = inventory;
                entities.add(inventory);
            }
        }

        if (equipmentDirty && config.sendEquipment()) {
            equipmentDirty = false;
            Map<String, Object> equipment = readEquipment(username);
            if (!Objects.equals(equipment, lastEquipment)) {
                lastEquipment = equipment;
                entities.add(equipment);
            }
        }

        if (entities.isEmpty()) return;
        eventBus.post(new HomeassistantEvents.UpdateEntities(entities));
    }

    private Map<String, Object> readInventory(String username) {
        List<Map<String, Object>> items = new ArrayList<>();
        ItemContainer container = client.getItemContainer(InventoryID.INV);
        if (container != null) {
            Item[] slots = container.getItems();
            for (int slot = 0; slot < slots.length && slot < INVENTORY_SLOTS; slot++) {
                Item item = slots[slot];
                if (item == null || item.getId() <= 0 || item.getQuantity() <= 0) continue;
                Map<String, Object> row = describe(item);
                row.put("slot", slot);
                items.add(row);
            }
        }

        Map<String, Object> attributes = new HashMap<>();
        attributes.put("entity_id", String.format("sensor.runelite_%s_inventory", username));
        attributes.put("items", items);
        attributes.put("used_slots", items.size());
        attributes.put("free_slots", INVENTORY_SLOTS - items.size());
        return attributes;
    }

    private Map<String, Object> readEquipment(String username) {
        Map<String, Object> worn = new LinkedHashMap<>();
        ItemContainer container = client.getItemContainer(InventoryID.WORN);
        if (container != null) {
            for (EquipmentInventorySlot slot : WORN_SLOTS) {
                Item item = container.getItem(slot.getSlotIdx());
                if (item == null || item.getId() <= 0 || item.getQuantity() <= 0) continue;
                worn.put(slot.name().toLowerCase(), describe(item));
            }
        }

        Map<String, Object> attributes = new HashMap<>();
        attributes.put("entity_id", String.format("sensor.runelite_%s_equipment", username));
        attributes.put("worn", worn);
        return attributes;
    }

    private Map<String, Object> describe(Item item) {
        Map<String, Object> row = new HashMap<>();
        row.put("id", item.getId());
        row.put("quantity", item.getQuantity());

        ItemComposition composition = itemManager.getItemComposition(item.getId());
        boolean noted = composition.getNote() != -1;
        if (noted) {
            composition = itemManager.getItemComposition(composition.getLinkedNoteId());
        }
        row.put("name", composition.getName());
        row.put("noted", noted);
        return row;
    }
}

package com.homeassistant.trackers;

import java.util.*;
import java.util.stream.Collectors;

import com.homeassistant.HomeassistantConfig;
import com.homeassistant.classes.StatusEffect;
import com.homeassistant.classes.Utils;
import com.homeassistant.trackers.events.HomeassistantEvents;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;

@Slf4j
@Singleton
public class PlayerDataTracker {
    private final EventBus eventBus;
    private final Client client;
    private final HomeassistantConfig config;
    private final int PING_TICK_INTERVAL = 100;


    private int currentHealth = 0;
    private int currentPrayer = 0;
    private int currentSpecialAttack = 0;
    private int currentRunEnergy = 0;
    private List<StatusEffect> currentStatusEffects = new ArrayList<>();
    private int previousHealth = 0;
    private int previousPrayer = 0;
    private int previousSpecialAttack = 0;
    private int previousRunEnergy = 0;
    private List<StatusEffect> previousStatusEffects = new ArrayList<>();
    private final Map<Skill, Integer> boostedSkills = new EnumMap<>(Skill.class);
    private final Map<Skill, Integer> previousBoostedSkills = new EnumMap<>(Skill.class);
    private final Map<Skill, Integer> skillXp = new EnumMap<>(Skill.class);
    private final Map<Skill, Integer> previousSkillXp = new EnumMap<>(Skill.class);

    private boolean previousIsOnline = false;
    private int previousOnlineWorld = -1;
    private boolean isOnline = false;
    private int onlineWorld = -1;
    private String lastUsername = null;

    @Inject
    public PlayerDataTracker(Client client, EventBus eventBus, HomeassistantConfig config)
    {
        this.client = client;
        this.eventBus = eventBus;
        this.config = config;

        for (Skill skill : Skill.values()) {
            boostedSkills.put(skill, 0);
            skillXp.put(skill, 0);
        }

        resetPrevious();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged gameStateChanged) {
        GameState gameState = gameStateChanged.getGameState();

        if(gameState == GameState.CONNECTION_LOST || gameState == GameState.LOGIN_SCREEN){
            logOutEvent();
        }

        if (gameState != GameState.LOGGED_IN) {
            return;
        }

        isOnline = true;
        onlineWorld = client.getWorld();
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (!config.playerRunEnergy() && !config.playerHealth() && !config.playerPrayer() && !config.playerSpecialAttack() && !config.playerOnlineStatus() && !config.skillBoosts() && !config.skillXp()){
            return;
        }

        Player player = client.getLocalPlayer();
        if (player == null || client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        String username = Utils.GetUserName(client);
        if (username == null) return;
        lastUsername = username;

        checkCurrentStats();
        checkAllEntities();

        if(client.getTickCount() % PING_TICK_INTERVAL == 0 && config.playerOnlineStatus()){
            pingEvent();
        }
    }

    private void checkAllEntities() {
        List<Map<String, Object>> entities = new ArrayList<>();
        if(currentHealth != previousHealth && config.playerHealth()){
            String entityId = String.format("sensor.runelite_%s_health", Utils.GetUserName(client));
            Map<String, Object> attributes = new HashMap<>();
            attributes.put("entity_id", entityId);
            attributes.put("current_health", currentHealth);
            entities.add(attributes);
        }
        if (currentPrayer != previousPrayer && config.playerPrayer())
        {
            String entityId = String.format("sensor.runelite_%s_prayer", Utils.GetUserName(client));
            Map<String, Object> attributes = new HashMap<>();
            attributes.put("entity_id", entityId);
            attributes.put("current_prayer", currentPrayer);
            entities.add(attributes);
        }
        if (currentSpecialAttack != previousSpecialAttack && config.playerSpecialAttack())
        {
            String entityId = String.format("sensor.runelite_%s_special_attack", Utils.GetUserName(client));
            Map<String, Object> attributes = new HashMap<>();
            attributes.put("entity_id", entityId);
            attributes.put("current_special_attack", currentSpecialAttack);
            entities.add(attributes);
        }
        if (currentRunEnergy != previousRunEnergy && config.playerRunEnergy())
        {
            String entityId = String.format("sensor.runelite_%s_run_energy", Utils.GetUserName(client));
            Map<String, Object> attributes = new HashMap<>();
            attributes.put("entity_id", entityId);
            attributes.put("current_run_energy", currentRunEnergy);
            entities.add(attributes);
        }
        if (!currentStatusEffects.equals(previousStatusEffects) && config.playerStatusEffects())
        {
            String entityId = String.format("sensor.runelite_%s_status_effects", Utils.GetUserName(client));
            Map<String, Object> attributes = new HashMap<>();
            attributes.put("entity_id", entityId);

            // Convert status effects to a serializable list of maps or strings
            List<Map<String, Object>> effectList = currentStatusEffects.stream()
                    .map(effect -> {
                        Map<String, Object> map = new HashMap<>();
                        map.put("name", effect.name);
                        map.put("number", effect.number);
                        map.put("time", effect.time);
                        return map;
                    })
                    .collect(Collectors.toList());

            attributes.put("current_status_effects", effectList);
            entities.add(attributes);
        }

        if(config.skillBoosts() || config.skillXp()){
            for (Skill skill : Skill.values()) {
                boolean boostChanged = config.skillBoosts()
                        && !Objects.equals(previousBoostedSkills.get(skill), boostedSkills.get(skill));
                boolean xpChanged = config.skillXp()
                        && !Objects.equals(previousSkillXp.get(skill), skillXp.get(skill));

                if (!boostChanged && !xpChanged) {
                    continue;
                }

                String entityId = String.format("sensor.runelite_%s_skill_%s", Utils.GetUserName(client), skill.getName().toLowerCase().replaceAll(" ", "_"));
                Map<String, Object> attributes = new HashMap<>();
                attributes.put("entity_id", entityId);
                if (config.skillBoosts()) {
                    attributes.put("virtual_level", boostedSkills.get(skill));
                }
                if (config.skillXp()) {
                    attributes.put("xp", skillXp.get(skill));
                }
                entities.add(attributes);
            }
        }


//		Player stats
        if((isOnline != previousIsOnline || onlineWorld != previousOnlineWorld) && config.playerOnlineStatus()) {
            Map<String, Object> attributes = new HashMap<>();
            attributes.put("entity_id", playerStatusEntityId());
            attributes.put("is_online", isOnline);
            attributes.put("world", onlineWorld);
            entities.add(attributes);
        }

        resetPrevious();

        if(entities.isEmpty()){
            return;
        }

        eventBus.post(new HomeassistantEvents.UpdateEntities(entities));
    }

    private void checkCurrentStats(){
        if(config.playerStatusEffects()){
            currentStatusEffects = new ArrayList<>();

            int poison = client.getVarpValue(102);
            boolean isPoisoned = false;
            boolean isVenomed = false;
            int damage = 0;

            if (poison > 0 && poison <= 100)
            {
                damage = (int) Math.ceil(poison / 5.0f);
                isPoisoned = true;

            }
            else if (poison >= 1_000_000)
            {
                damage = Math.min(20, (poison - 999_997) * 2);
                isVenomed = true;
            }

            if(isPoisoned || isVenomed){
                StatusEffect statusEffect = new StatusEffect();
                statusEffect.number = damage;
                statusEffect.name = isPoisoned ? "Poison" : "Venom";
                currentStatusEffects.add(statusEffect);
            }
        }

        if(config.playerRunEnergy())
            currentRunEnergy = client.getEnergy() / 100;

        if(config.playerSpecialAttack())
            currentSpecialAttack = client.getVarpValue(300) / 10;

        if(config.playerHealth())
            currentHealth = client.getBoostedSkillLevel(Skill.HITPOINTS);

        if(config.playerPrayer())
            currentPrayer = client.getBoostedSkillLevel(Skill.PRAYER);

        if(config.skillBoosts()){
            for (Skill skill : Skill.values()) {
                boostedSkills.put(skill, client.getBoostedSkillLevel(skill));
            }
        }

        if(config.skillXp()){
            for (Skill skill : Skill.values()) {
                skillXp.put(skill, client.getSkillExperience(skill));
            }
        }
    }

    private void resetPrevious(){
        previousHealth = currentHealth;
        previousPrayer = currentPrayer;
        previousRunEnergy = currentRunEnergy;
        previousSpecialAttack = currentSpecialAttack;
        previousStatusEffects = new ArrayList<>();
        for (StatusEffect value : currentStatusEffects ){
            previousStatusEffects.add(value.copy());
        }
        previousIsOnline = isOnline;
        previousOnlineWorld = onlineWorld;

        for (Skill skill : Skill.values()) {
            previousBoostedSkills.put(skill, boostedSkills.get(skill));
            previousSkillXp.put(skill, skillXp.get(skill));
        }
    }

    private void logOutEvent(){
        isOnline = false;
        onlineWorld = -1;
        if (lastUsername == null && Utils.GetUserName(client) == null) return;

        Map<String, Object> attributes = new HashMap<>();
        attributes.put("entity_id", playerStatusEntityId());
        attributes.put("is_online", isOnline);
        attributes.put("world", onlineWorld);

        List<Map<String, Object>> entities = new ArrayList<>();
        entities.add(attributes);
        Map<String, Object> payload = new HashMap<>();
        payload.put("entities", entities);

        eventBus.post(new HomeassistantEvents.SendEvent(payload, "set_multi_entity_data"));
        resetPrevious();
    }

    private void pingEvent(){
        Map<String, Object> attributes = new HashMap<>();
        attributes.put("entity_id", playerStatusEntityId());
        attributes.put("is_online", isOnline);
        attributes.put("world", onlineWorld);

        List<Map<String, Object>> entities = new ArrayList<>();
        entities.add(attributes);
        Map<String, Object> payload = new HashMap<>();
        payload.put("entities", entities);

        eventBus.post(new HomeassistantEvents.SendEvent(payload, "set_multi_entity_data"));
    }

    private String playerStatusEntityId(){
        String username = Utils.GetUserName(client);
        if (username != null) {
            lastUsername = username;
        }
        return String.format("sensor.runelite_%s_player_status", lastUsername);
    }
}

package com.homeassistant.trackers;

import com.homeassistant.HomeassistantConfig;
import com.homeassistant.classes.Utils;
import com.homeassistant.runelite.quest.QuestVarPlayer;
import com.homeassistant.runelite.quest.QuestVarbits;
import com.homeassistant.trackers.events.HomeassistantEvents;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/**
 * Reports the quest being worked on, from the varbit or varplayer that holds
 * its progress stage.
 */
@Slf4j
@Singleton
public class QuestTracker {
    private static final String PREFIX = "QUEST_";
    private static final int COMPLETE_MAX_TICKS = 10;
    private static final Map<String, String> ALIASES = Map.of(
            "DESERTTREASURE", "DESERTTREASUREI",
            "DESERTTREASUREII", "DESERTTREASUREIIFALLENEMPIRE",
            "RECIPEFORDISASTERDWARF", "RECIPEFORDISASTERMOUNTAINDWARF",
            "RECIPEFORDISASTERMONKEYAMBASSADOR", "RECIPEFORDISASTERKINGAWOWOGEI",
            "MAGEARENA", "MAGEARENAI"
    );

    private final HomeassistantConfig config;
    private final EventBus eventBus;
    private final Client client;

    private final Map<Integer, String> byVarbit = new HashMap<>();
    private final Map<Integer, String> byVarp = new HashMap<>();
    private final Map<String, Quest> quests = new HashMap<>();
    private final Map<String, Integer> lastValues = new HashMap<>();
    private final Map<String, String> lastStates = new HashMap<>();

    private Map<String, Object> lastSent = null;
    private String currentQuest = null;
    private int currentStage = 0;
    private boolean sendOnTick = false;
    private boolean seedStates = false;
    private boolean testRequested;
    private String completedQuest = null;
    private int completeTicksLeft = 0;
    private boolean pointsChanged = false;
    private int pointsChangedTick = -1;

    @Inject
    public QuestTracker(EventBus eventBus, Client client, HomeassistantConfig config) {
        this.eventBus = eventBus;
        this.client = client;
        this.config = config;
        this.testRequested = config.testQuestCompleteEvent();

        Map<String, Quest> byKey = new HashMap<>();
        for (Quest quest : Quest.values()) {
            byKey.put(key(quest.name()), quest);
        }
        for (QuestVarbits varbit : QuestVarbits.values()) {
            String name = questName(varbit.name(), byKey);
            if (name != null) byVarbit.put(varbit.getId(), name);
        }
        for (QuestVarPlayer varp : QuestVarPlayer.values()) {
            String name = questName(varp.name(), byKey);
            if (name != null) byVarp.put(varp.getId(), name);
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        GameState state = event.getGameState();
        if (state != GameState.LOGGING_IN && state != GameState.HOPPING) return;

        lastValues.clear();
        lastStates.clear();
        currentQuest = null;
        currentStage = 0;
        lastSent = null;
        sendOnTick = true;
        seedStates = true;
    }

    @Subscribe
    public void onGameTick(GameTick tick) {
        if (seedStates) {
            seedStates = false;
            // Baseline, so a completion is measured against a real previous state.
            for (Quest quest : quests.values()) {
                lastStates.put(quest.getName(), stateOf(quest.getName()));
            }
        }

        if (sendOnTick) {
            sendOnTick = false;
            send();

            if (currentQuest != null) {
                String state = stateOf(currentQuest);
                String was = lastStates.put(currentQuest, state);
                // A quest seen for the first time is not a transition.
                if (was != null && "FINISHED".equals(state) && !"FINISHED".equals(was)) {
                    completedQuest = currentQuest;
                    completeTicksLeft = COMPLETE_MAX_TICKS;
                    pointsChanged = client.getTickCount() - pointsChangedTick <= 1;
                }
            }
        }

        if (completedQuest == null) return;
        if (!pointsChanged && --completeTicksLeft > 0) return;

        if (config.sendQuestCompleteEvents()) {
            sendComplete(completedQuest, client.getVarpValue(VarPlayerID.QP));
        }
        completedQuest = null;
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!HomeassistantConfig.CONFIG_GROUP.equals(event.getGroup())) return;

        if (!testRequested && config.testQuestCompleteEvent()) {
            sendComplete("Test Quest", 0);
        }
        testRequested = config.testQuestCompleteEvent();
    }

    private void sendComplete(String quest, int questPoints) {
        Map<String, Object> completed = new HashMap<>();
        completed.put("quest", quest);
        completed.put("quest_points", questPoints);
        eventBus.post(new HomeassistantEvents.SendEvent(completed, "trigger_quest_complete_notify"));
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event) {
        if (!config.sendQuestProgress()) return;

        boolean points = event.getVarbitId() == -1 && event.getVarpId() == VarPlayerID.QP;
        if (points || event.getVarbitId() == VarbitID.QUESTS_COMPLETED_COUNT) {
            Integer previous = lastValues.put(points ? "qp" : "completed", event.getValue());
            if (previous == null || previous == event.getValue()) return;

            log.debug("Quest {} changed: {} -> {}", points ? "points" : "count", previous, event.getValue());
            if (points) {
                pointsChanged = true;
                pointsChangedTick = client.getTickCount();
            }
            sendOnTick = true;
            return;
        }

        String quest;
        String key;
        if (event.getVarbitId() != -1) {
            quest = byVarbit.get(event.getVarbitId());
            key = "b" + event.getVarbitId();
        } else {
            quest = byVarp.get(event.getVarpId());
            key = "p" + event.getVarpId();
        }
        if (quest == null) return;

        Integer previous = lastValues.put(key, event.getValue());
        if (previous == null || previous == event.getValue()) return;

        currentQuest = quest;
        currentStage = event.getValue();
        sendOnTick = true;
    }

    private String questName(String constant, Map<String, Quest> byKey) {
        if (!constant.startsWith(PREFIX) || constant.equals("QUEST_TAB")) return null;

        String name = constant.substring(PREFIX.length()).replaceAll("_STATE_\\d+$", "");
        String key = key(name);
        Quest quest = byKey.get(ALIASES.getOrDefault(key, key));
        if (quest == null) return readable(name);

        quests.put(quest.getName(), quest);
        return quest.getName();
    }

    private static String key(String constant) {
        StringBuilder out = new StringBuilder();
        for (String word : constant.split("_")) {
            if (!word.equals("THE") && !word.equals("AND")) out.append(word);
        }
        return out.toString();
    }

    private String readable(String name) {
        StringBuilder out = new StringBuilder();
        for (String word : name.toLowerCase().split("_")) {
            if (word.isEmpty()) continue;
            if (out.length() > 0) out.append(' ');
            if (word.matches("[ivx]+")) {
                out.append(word.toUpperCase());
            } else {
                out.append(Character.toUpperCase(word.charAt(0))).append(word.substring(1));
            }
        }
        return out.toString();
    }

    private String stateOf(String quest) {
        Quest match = quests.get(quest);
        if (match == null) return "UNKNOWN";

        QuestState state = match.getState(client);
        return state == null ? "UNKNOWN" : state.name();
    }

    private void send() {
        if (!config.sendQuestProgress()) return;

        Map<String, Object> attributes = new HashMap<>();
        attributes.put("entity_id",
                String.format("sensor.runelite_%s_last_quest", Utils.GetUserName(client)));
        attributes.put("quest", currentQuest == null ? "None" : currentQuest);
        attributes.put("state", currentQuest == null ? "NONE" : stateOf(currentQuest));
        attributes.put("stage", currentStage);
        attributes.put("quest_points", client.getVarpValue(VarPlayerID.QP));
        attributes.put("completed", client.getVarbitValue(VarbitID.QUESTS_COMPLETED_COUNT));
        attributes.put("total", client.getVarbitValue(VarbitID.QUESTS_TOTAL_COUNT));

        if (Objects.equals(lastSent, attributes)) return;
        lastSent = attributes;

        log.debug("Quest: {} (stage {}, {})", attributes.get("quest"),
                attributes.get("stage"), attributes.get("state"));

        List<Map<String, Object>> entities = new ArrayList<>();
        entities.add(attributes);
        eventBus.post(new HomeassistantEvents.UpdateEntities(entities));
    }
}

package com.homeassistant.trackers;

import com.homeassistant.HomeassistantConfig;
import com.homeassistant.classes.Utils;
import com.homeassistant.trackers.events.HomeassistantEvents;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/**
 * Reports the current slayer task.
 *
 * The task is read from RuneLite's own Slayer plugin rather than from varbits.
 * That plugin already maintains the task name, the counts and the location, and
 * writes them to the "slayer" config group -- which is the same source the
 * !task chat command reads. Reusing it means no creature-id lookup table to
 * keep in sync with the game, and it picks up every correction the Slayer
 * plugin makes (task assignment, partial completion, task cancellation).
 *
 * The trade-off is a hard requirement: RuneLite's Slayer plugin has to be
 * enabled, otherwise nothing writes those keys and this stays empty.
 */
@Slf4j
@Singleton
public class SlayerTracker {
    private static final String SLAYER_GROUP = "slayer";
    private static final String TASK_NAME_KEY = "taskName";
    private static final String AMOUNT_KEY = "amount";
    private static final String INIT_AMOUNT_KEY = "initialAmount";
    private static final String TASK_LOC_KEY = "taskLocation";
    private static final String STREAK_KEY = "streak";
    private static final String POINTS_KEY = "points";

    private final HomeassistantConfig config;
    private final EventBus eventBus;
    private final Client client;
    private final ConfigManager configManager;

    private Map<String, Object> lastSent = null;
    private boolean pendingLogin = false;

    @Inject
    public SlayerTracker(EventBus eventBus, Client client, ConfigManager configManager,
                         HomeassistantConfig config) {
        this.eventBus = eventBus;
        this.client = client;
        this.configManager = configManager;
        this.config = config;
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!SLAYER_GROUP.equals(event.getGroup())) return;

        // The Slayer plugin writes several keys per change, so this fires a few
        // times in a row for one task update. sendTask() compares against what
        // was last sent, so the duplicates collapse.
        sendTask();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        // On login the config is already populated but nothing has changed, so
        // without this the task would only appear after the first kill.
        if (event.getGameState() == GameState.LOGGED_IN) {
            lastSent = null;
            pendingLogin = true;
        }
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        if (!pendingLogin || Utils.GetUserName(client) == null) return;
        pendingLogin = false;
        sendTask();
    }

    private String readString(String key) {
        String value = configManager.getRSProfileConfiguration(SLAYER_GROUP, key);
        return value == null || value.isEmpty() ? null : value;
    }

    private int readInt(String key) {
        String value = readString(key);
        if (value == null) return 0;
        try {
            return Integer.parseInt(value.trim());
        } catch (NumberFormatException e) {
            return 0;
        }
    }

    private void sendTask() {
        if (!config.sendSlayerTask()) return;

        String username = Utils.GetUserName(client);
        if (username == null) return;

        String task = readString(TASK_NAME_KEY);

        Map<String, Object> attributes = new HashMap<>();
        attributes.put("entity_id",
                String.format("sensor.runelite_%s_slayer_task", username));
        // No task is a state worth reporting, not a reason to send nothing --
        // otherwise a finished task would leave the last one on screen forever.
        attributes.put("task", task == null ? "None" : task);
        attributes.put("remaining_amount", task == null ? 0 : readInt(AMOUNT_KEY));
        attributes.put("initial_amount", task == null ? 0 : readInt(INIT_AMOUNT_KEY));
        attributes.put("task_location", task == null ? "" : String.valueOf(readString(TASK_LOC_KEY)));
        attributes.put("streak", readInt(STREAK_KEY));
        attributes.put("points", readInt(POINTS_KEY));

        if (Objects.equals(lastSent, attributes)) return;
        lastSent = attributes;

        log.debug("Slayer task: {} ({} left)", attributes.get("task"),
                attributes.get("remaining_amount"));

        List<Map<String, Object>> entities = new ArrayList<>();
        entities.add(attributes);
        eventBus.post(new HomeassistantEvents.UpdateEntities(entities));
    }
}

package com.homeassistant.trackers;

import com.homeassistant.HomeassistantConfig;
import com.homeassistant.trackers.events.HomeassistantEvents;
import com.homeassistant.trackers.events.InternalEvents;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;

@Slf4j
@Singleton
public class VarbitTracker {

    private final Client client;
    private final EventBus eventBus;
    private final HomeassistantConfig config;

    private final Map<Integer, Integer> previousVarbitValues = new HashMap<>();
    private final List<Integer> watchedVarbitIds = new ArrayList<>();

    private final Map<String, List<Integer>> internalVarbitIds = new HashMap<>();
    private final Map<String, Map<Integer, Integer>> previousInternalVarbitIds = new HashMap<>();

    @Inject
    public VarbitTracker(Client client, EventBus eventBus, HomeassistantConfig config) {
        this.client = client;
        this.eventBus = eventBus;
        this.config = config;

        parseWatchedVarbits();
    }

    public void setInternalWatch(String id, List<Integer> varbitIds) {
        setInternalWatch(id, varbitIds, null); // default to null
    }

    public void setInternalWatch(String id, List<Integer> varbitIds, Integer overrideValue){
        Map<Integer, Integer> values = new HashMap<>();
        for (int varbitId : varbitIds) {
            if(!previousInternalVarbitIds.containsKey(id)){
                values.put(varbitId, overrideValue);
            }else{
                values.put(varbitId, previousInternalVarbitIds.get(id).get(varbitId));
            }
        }

        internalVarbitIds.put(id, varbitIds);
        previousInternalVarbitIds.put(id, values);

        log.info("Watching internal varbits: {}, {}", id, varbitIds);
    }

    private void parseWatchedVarbits() {
        watchedVarbitIds.clear();
        previousVarbitValues.clear();

        String input = config.varbitIdsEvent();
        log.debug("input {}",input);
        if (input == null || input.isBlank()) return;

        for (String part : input.split(",")) {
            try {
                int id = Integer.parseInt(part.trim());

                watchedVarbitIds.add(id);
                previousVarbitValues.put(id, null); // initialize value
            } catch (NumberFormatException e) {
                log.warn("Invalid varbit ID in config: {}", part.trim());
            }
        }

        log.info("Watching varbits: {}", watchedVarbitIds);
    }

    @Subscribe
    public void onGameTick(GameTick tick) {
        Player player = client.getLocalPlayer();
        if (player == null) return;

        if (!watchedVarbitIds.isEmpty()) {
            for (int varbitId : watchedVarbitIds) {
                int current = client.getVarbitValue(varbitId);
                Integer previous = previousVarbitValues.get(varbitId);

                if (previous != null && current != previous) {
                    log.debug("Varbit {} changed: {} -> {}", varbitId, previous, current);

                    Map<String, Object> data = new HashMap<>();
                    data.put("varbit_id", varbitId);
                    data.put("new_value", current);
                    data.put("old_value", previous);

                    eventBus.post(new HomeassistantEvents.SendEvent(data, "trigger_varbit_change_notify"));
                }

                previousVarbitValues.put(varbitId, current);
            }
        }

        if(!internalVarbitIds.isEmpty()){
            for(String internalId : internalVarbitIds.keySet()){
                List<Integer> values = internalVarbitIds.get(internalId);
                if (!values.isEmpty()){
                    for (int varbitId : values) {

                        int current = client.getVarbitValue(varbitId);
                        Integer previous = previousInternalVarbitIds.get(internalId).get(varbitId);

                        if (previous != null && previous != current) {
                            log.debug("Internal Varbit {} changed: {} -> {}", internalId, previous, current);
                            eventBus.post(new InternalEvents.VarbitUpdate(internalId, varbitId, previous, current));
                        }

                        previousInternalVarbitIds.get(internalId).put(varbitId, current);
                    }
                }

            }
        }
    }

    @Subscribe
    public void onConfigChanged(net.runelite.client.events.ConfigChanged event) {
        if (event.getGroup().equals(HomeassistantConfig.CONFIG_GROUP)) {
            parseWatchedVarbits();
        }
    }
}

